import{_ as s,o as p,c as i,a3 as a}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"阻尼理论与其修正和扩展（优先输出）","description":"","frontmatter":{"translationSource":{"title":"阻尼理论与其修正和扩展（优先输出）","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JN3ceSWPVQFlqvlfOsiR7k","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/damping-theory-revisions-and-extensions"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revisions-and-extensions"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/damping-theory-revisions-and-extensions"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revisions-and-extensions"}]]},"headers":[],"relativePath":"zh/damping-theory-revisions-and-extensions.md","filePath":"zh/page-JN3ceSWPVQFlqvlfOsiR7k.md"}'),c={name:"zh/damping-theory-revisions-and-extensions.md"};function d(t,e,o,l,n,r){return p(),i("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><h1 id="阻尼理论与其修正和扩展-优先输出" tabindex="-1">阻尼理论与其修正和扩展（优先输出） <a class="header-anchor" href="#阻尼理论与其修正和扩展-优先输出" aria-label="Permalink to &quot;阻尼理论与其修正和扩展（优先输出）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>JN3ceSWPVQFlqvlfOsiR7k</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JN3ceSWPVQFlqvlfOsiR7k" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>阻尼理论由@jnk 创作并整理维护，@c、@苍孤狼、@苍蓝泥沼 等人提供丰富的验证</p><p><span class="mark-red">阻尼理论已经过时，最新理论请参见</span><a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>，本文档作为归档文件记录探索的来路。</p><p>这里使用物流线的说法，<em>物流线</em>：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8fcd80a97a7d923a.q90-3ab578c216c3cc2c.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>简单来说，物流线是从工厂出口到物流结构末尾所有可能的物品路线，如红线所示。末尾不是工厂入口的被称为断尾物流线。</p><p><em>物流线的阻尼</em>：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-db2412e650aacf6c.q90-900d91ad5f92aae5.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>物流线上的物流元件个数为其的阻尼，包括工厂入口，整个传送带被视为一个物流元件，物流桥的不同方向被视为不同物流元件。</p><p>出于过去的计算的兼容，我们一般从下游往上游数有多少个物流元件，从上游向下游数结果当然是一样的。</p><p>出于对过去的计算的兼容，在我们日常讨论时一般会减一，在本文中不会这么做。</p><p><em>连接顺序</em>：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-715107987777682b.q90-c03c4b9f3365c545.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>这是一种有序数据结构，存放了下游工厂关于放置顺序的一些数据。</p><p>具体的，当工厂入口被物流元件连接时，如果它不在连接顺序中，就加到末尾；</p><p>当工厂入口连接的物流元件被收纳时，如果工厂入口不再有任何连接，则从连接顺序中删除。</p><p>这张图与之后的图都用黑色表示连接顺序，红色表示阻尼与物流线。</p><p>当我们说按连接顺序时，就是按从前往后（往末尾）遍历这里的工厂</p><p><em>出口阻尼</em></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-be4fb24402851a12.q90-c5f37be6c65c4982.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>每个出口可能对应多个物流线，但是其只会选取其中一个的阻尼作为出口阻尼，即一个出口只有一个阻尼，具体计算见阻尼理论，用途也是。</p><p><em>阻尼理论</em></p><p>一种解释工厂出口有时存在优先级现象时的理论，我们说阻尼理论时通常是在解释优先输出现象。</p><p>首先从上游向下游遍历断开物流元件连接中的环，即从上游向下游数，如果遇到数过的就把中间断开。然后计算所有还存在的物流线</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e187546d03bd1d3.q90-24bda214b4c1536b.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>这里橙色的叉是断开环时断开的连接</p><p>按照连接顺序取出一个工厂，计算所有连接到这个工厂的物流线的阻尼，这些物流线连接的工厂出口的阻尼取其对应的物流线的阻尼中最小的，在后续计算中就不会再被覆盖了。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-24b791e74672f96d.q90-cc36e220e9f59478.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>连接顺序1</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ac408238404a797f.q90-b248825efe8a10c9.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>连接顺序2</p><p>如果工厂出口没有全部计算完毕，就继续使用断尾物流线的阻尼计算，同样取其中最小的，且不能覆盖之前的结果。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-37f949889afbfbd5.q90-18cd325636e3f1af.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>对于同一个工厂的多个出口，使其中所有非汇流器开头的出口变成相同的最大的阻尼。这被称为同化</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a4944bcf0b8c8866.q90-0ce8c8e66b1f0e8e.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>同化效果</p><p>最后，阻尼小的出口优先级高，先放下开头的物流元件的出口优先度高。先看优先级，再看优先度。对于非汇流器开头的那些出口，如果优先，会在其中轮询。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1db17cff47b3f11b.q90-c2f4660c3abee22e.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>接下来让我们欣赏成果</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c90fe719ce5e3679.q90-6ad1c45baa6f0ddd.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p><em><strong>需要注意的点</strong></em></p><p>优先级不是把非优先的都堵了，优先的路线速度不足以输出所有物品时，会从其他非优先的线路输出。</p><p>阻尼理论只规定了工厂出口的优先级，而不是物流线的优先级，即使阻尼大的物流线，也可以由分流器分流到物品。</p><p>不是所有工厂出口都遵循阻尼理论，例如(扩容)反应池。</p><p>水管的暗管出口在多次测试中同样符合这套理论，但是其他如反应池就不符合，没有优先输出现象。</p><p>阻尼理论是经验的，而不可能是底层原理。</p><p>特别的，反应池与扩容反应池的物品输出不遵循阻尼理论，除了多口暗管出口以外的液体输出都不遵循阻尼理论，它们不会产生优先级</p><p>对于存在环的情况，阻尼理论并不总是正确的，如果你观察到不符合理论的现象，请描述在下面。</p><p><strong>bugs：</strong></p><p>~~当某些工厂出口的汇流器属于一个环并且符合某些特殊条件时，工厂出口会轮询而不是优先级，具体条件需要进一步测试。~~已验证 顺环 结构导致4*1卡1s现象，非优先级问题</p><p>箱子出口汇流器属于环中时，优先级会有异常，可以切换，以下是来自@恒星泰斗 的研究结果</p><p><a href="/endfield-skydoc/logistics/src/assets/attachments/关于顺旋的研究.docx-eb529678ae47fb09.docx">附件：关于顺旋的研究.docx</a></p><blockquote><p>原件：关于顺旋的研究.docx；大小：634595；objKey：<code>098c4738561242e8a3a31150bfbd5299</code>；本地状态：已下载。</p></blockquote><p>@恒星泰斗 发现以下内容，见聊天记录</p><details><summary>断尾物流线的意外情况</summary><p>恒星泰斗 1:11:21</p><p>之前我测过一个。箱子a三条路连向箱子b，其中两条路用分流器连向箱子c和d。阻尼会按照箱子的顺序计算，先放的箱子优先</p><p>然后把箱子cd用物流桥代替，有时也能看到类似的现象。</p><p>但是如果用传递带，或者用分流器分离出多条路并且这些路末端都不是箱子，就不行</p><p>另外，前面不接任何物流器，直连箱子的断头路会展现出和阻尼理论相反的情况。后放优先级更高</p><p>但是在这个断头路上加任何物流器，就会变成阻尼理论的情况</p></details><p><span class="mark-red">经验证，该现象属实，修正对断头传送带的描述，修正内容在本段内容末尾的阻尼理论-改中。</span></p><p>@c 发现断尾物流线的阻尼有异常现象，如图，优先级最高的是中间的</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ef37b02b4136e5bb.q90-8dbd470a87102115.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>经验证，该现象属实，修正对断头传送带的描述，修正内容在本段内容末尾的阻尼理论-改中。</p><p>@jnk 注意到4n卡1s中出现的阻尼计算中断尾物流线存在一定异常，如下图所示</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-be837f85aea7a1a3.q90-5fdc998e1d7d6a14.webp" alt="阻尼理论与其修正和扩展（优先输出）"></p><p>断头物流线末尾的物流器有时可以视作类似存储箱的事物。</p><p>经验证，修正对断头传送带的描述，修正内容在本段内容末尾的阻尼理论-改中。</p><p><a href="/endfield-skydoc/zh/damping-theory-revised">阻尼理论-改</a></p><p><strong>阻尼理论的扩展</strong></p><p>阻尼在断开环后大部分时候可以完美符合层级BFS论，即计算移动时从下游BFS，但是每层内按照放置顺序进行输入的BFS访问</p><p>等待其他扩展...</p></div>',1)])])}const f=s(c,[["render",d]]);export{m as __pageData,f as default};
